<div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><div><a href="<?= url('/customers') ?>">← Customers</a><h2 class="mt-2 mb-0"><?= e($customer['name']) ?></h2><p class="text-secondary mb-0"><?= e($customer['customer_code'].' · '.$customer['customer_type']) ?></p></div><div class="d-flex gap-2"><button class="btn btn-outline-secondary metadata-btn" data-entity="customer" data-id="<?= $customer['id'] ?>"><i class="bi bi-tags"></i> Metadata</button><button class="btn btn-outline-secondary collab-btn" data-entity="customer" data-id="<?= $customer['id'] ?>"><i class="bi bi-chat-left-text"></i> Notes & Documents</button><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#contactModal"><i class="bi bi-person-plus"></i> Contact</button></div></div>
<div class="row g-3 mb-3"><div class="col-lg-4"><div class="card-panel h-100"><h3 class="h6">Profile</h3><div class="report-row"><span>Company</span><strong><?= e($customer['company']??'-') ?></strong></div><div class="report-row"><span>Phone</span><strong><?= e($customer['phone']??'-') ?></strong></div><div class="report-row"><span>WhatsApp</span><strong><?= e($customer['whatsapp']??'-') ?></strong></div><div class="report-row"><span>Email</span><strong><?= e($customer['email']??'-') ?></strong></div><hr><small class="text-secondary">Billing Address</small><p><?= nl2br(e($customer['billing_address']??'-')) ?></p><small class="text-secondary">Service Address</small><p class="mb-0"><?= nl2br(e($customer['service_address']??'-')) ?></p></div></div><div class="col-lg-8"><div class="card-panel h-100"><h3 class="h6">Contacts</h3><div class="row g-2"><?php foreach($contacts as $c): ?><div class="col-md-6"><div class="border rounded-3 p-3 h-100"><div class="d-flex justify-content-between"><strong><?= e($c['name']) ?></strong><?php if($c['is_primary']): ?><span class="status-badge success">Primary</span><?php endif; ?></div><small class="text-secondary"><?= e($c['position']??'') ?></small><div class="mt-2"><?= e($c['phone']??'-') ?> · <?= e($c['email']??'-') ?></div></div></div><?php endforeach; ?><?php if(!$contacts): ?><div class="text-secondary">No contacts yet.</div><?php endif; ?></div></div></div></div>
<div class="row g-3 mb-3"><div class="col-lg-6"><div class="card-panel"><h3 class="h6">Sites</h3><?php foreach($sites as $s): ?><div class="report-row"><span><strong><?= e($s['site_name']) ?></strong><small><?= e($s['address']) ?></small></span><span><?= e($s['contact_person']??'') ?></span></div><?php endforeach; ?></div></div><div class="col-lg-6"><div class="card-panel"><h3 class="h6">Assets</h3><?php foreach($assets as $a): ?><div class="report-row"><span><strong><?= e($a['asset_code']) ?></strong><small><?= e(($a['brand']??'').' '.($a['model']??'')) ?></small></span><a class="btn btn-sm btn-light" href="<?= url('/assets/'.$a['id'].'/qr') ?>"><i class="bi bi-qr-code"></i></a></div><?php endforeach; ?></div></div></div>
<div class="row g-3"><div class="col-lg-7"><div class="card-panel"><h3 class="h6">Recent Jobs</h3><?php foreach($jobs as $j): ?><div class="report-row"><span><a href="<?= url('/jobs/'.$j['id']) ?>"><strong><?= e($j['job_number']) ?></strong></a><small><?= e($j['description']) ?></small></span><span class="status-badge"><?= e($j['status']) ?></span></div><?php endforeach; ?></div></div><div class="col-lg-5"><div class="card-panel"><h3 class="h6">Invoices</h3><?php foreach($invoices as $i): ?><div class="report-row"><span><a href="<?= url('/invoices/'.$i['id']) ?>"><strong><?= e($i['invoice_number']) ?></strong></a><small>Due <?= e($i['due_date']??'-') ?></small></span><span><strong><?= e(money($i['balance'])) ?></strong><small class="d-block text-end"><?= e($i['status']) ?></small></span></div><?php endforeach; ?></div></div></div>
<div class="modal fade" id="contactModal"><div class="modal-dialog"><form class="modal-content ajax-form" method="post" action="<?= url('/customers/'.$customer['id'].'/contacts') ?>"><?= csrf_field() ?><div class="modal-header"><h5>New Contact</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">Name</label><input class="form-control mb-2" name="name" required><label class="form-label">Position</label><input class="form-control mb-2" name="position"><div class="row g-2"><div class="col-6"><label class="form-label">Phone</label><input class="form-control" name="phone"></div><div class="col-6"><label class="form-label">WhatsApp</label><input class="form-control" name="whatsapp"></div></div><label class="form-label mt-2">Email</label><input class="form-control" type="email" name="email"><div class="form-check mt-3"><input class="form-check-input" type="checkbox" name="is_primary" value="1" id="primaryContact"><label class="form-check-label" for="primaryContact">Primary contact</label></div></div><div class="modal-footer"><button class="btn btn-primary">Save Contact</button></div></form></div></div>
